(* [comment removed for export] *)
Definition pcl_post (q p ap : Z) (gp tp s0 s2 s4 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s6 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR ra (Z_to_bv 64 (q + -2240)) gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 (Z_to_bv 64 p) s4 (Z_to_bv 64 ap)
                  s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x59ebc) fc None m' (seg_rom asegs)
    /\ munch [(q + -2320, q + -2240); (q + -2216, q + -2176)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (q + -2240)
    /\ (exists junk, rw_cells asegs m' (q + -2216) [CB 40 junk]).

Section WithRIP.
Hypothesis RIP : rip_stmt.

Lemma pcom_dstr_last_spec : forall (q p ap S : Z) (str : list byte) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem),
  sp = Z_to_bv 64 (q + -2240) -> s0 = Z_to_bv 64 q -> s2 = Z_to_bv 64 10 -> s3 = Z_to_bv 64 p -> s4 = Z_to_bv 64 90432 ->
  s5 = Z_to_bv 64 ap -> s7 = Z_to_bv 64 9 -> s8 = Z_to_bv 64 (q + -2184) -> s10 = Z_to_bv 64 (-1) -> s11 = Z_to_bv 64 37 ->
  bytes_at asegs m p (zb8 [37; 115; 0]) -> rw_cells asegs m (q + -2216) DIR0 ->
  ro_cells asegs m ap [C8 (Z_to_bv 64 S)] -> q <= ap -> ap + 8 < 2^63 ->
  cstr_at m S str -> 0 < S -> (S + Z.of_nat (length str) + 1 <= lo \/ q <= S) -> S + Z.of_nat (length str) + 1 < 2^47 ->
  chk_ok m S (Z.of_nat (length str) + 1) -> pctx m ->
  stk asegs m lo (q + -2240) -> lo <= q + -2320 -> kHighShadowEnd + 8 <= lo -> p + 3 <= lo -> q <= 2^47 ->
  mem_inv asegs m ->
  evt asegs (pcl_post q (p + 2) (ap + 8) gp tp s0 s2 s4 s7 s8 s9 s10 s11 F fc lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
